// --- Physics (movement + wall/paddle bounces) ------------------------------

// Brick bounce (pure logic, called from step). For each overlapping live
// brick: destroy it, score it, and flip the velocity along the axis of the
// smallest penetration (side face => vx, top/bottom face => vy; equal
// penetrations resolve on vx until the corner case is handled).

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle AND the bricks (brick logic moved here from the
// render loop; see the playtest spec in .scratch/to_fix.md).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks (pure logic).
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Axis of the bounce = axis of the smallest penetration.
    const overlapX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
    const overlapY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
    if (overlapX < overlapY) {
      ball.vx = -ball.vx;
    } else {
      ball.vy = -ball.vy;
    }
  }

