for (const brick of hits) {
  // Axis of the bounce = axis of the smallest penetration. Equal
  // penetrations mean the ball hit a corner: BOTH axes bounce (playtest D4).
  const overlapX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const overlapY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  const corner = Math.abs(overlapX - overlapY) <= 1e-9;
  if (corner || overlapX < overlapY) {
    if (!flippedVx) {
      ball.vx = -ball.vx;
      flippedVx = true;
      // Push the ball out, on the side it is now heading away from.
      bounceX = ball.vx < 0 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    }
  }
  if (corner || overlapY < overlapX) {
    if (!flippedVy) {
      ball.vy = -ball.vy;
      flippedVy = true;
      bounceY = ball.vy < 0 ? brick.y - ball.r : brick.y + brick.h + ball.r;
    }
  }
}

