// --- Physics (movement + wall/paddle bounces) ------------------------------

// Swept ball vs brick: does the segment from `prev` to `ball` (ball center,
// radius `r`) touch the brick's AABB inflated by `r`? Returns the contact
// point (ball center), the entry time in [0, 1] and the face that was hit, or
// null when the segment misses. A discrete sample test would let a step
// longer than the brick jump straight over it (playtest D5): the slab test
// below catches the crossing no matter the step length.
function sweepBall(prev, ball, brick, r) {
  const minX = brick.x - r;
  const minY = brick.y - r;
  const maxX = brick.x + brick.w + r;
  const maxY = brick.y + brick.h + r;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  let t1x = -Infinity;
  let t2x = Infinity;
  if (dx === 0) {
    if (prev.x < minX || prev.x > maxX) return null; // parallel, outside
  } else {
    t1x = (minX - prev.x) / dx;
    t2x = (maxX - prev.x) / dx;
    if (t1x > t2x) [t1x, t2x] = [t2x, t1x];
  }

  let t1y = -Infinity;
  let t2y = Infinity;
  if (dy === 0) {
    if (prev.y < minY || prev.y > maxY) return null; // parallel, outside
  } else {
    t1y = (minY - prev.y) / dy;
    t2y = (maxY - prev.y) / dy;
    if (t1y > t2y) [t1y, t2y] = [t2y, t1y];
  }

  const tMin = Math.max(t1x, t1y);
  const tMax = Math.min(t2x, t2y);
  if (tMin > tMax || tMax < 0 || tMin > 1) return null;
  const t = Math.max(0, tMin);

  // Entry face: which slab constrains the entry? Both at once = a corner hit
  // (the ball grazes the brick corner exactly, equal penetrations on both
  // axes — playtest D4: BOTH velocities bounce).
  const eps = 1e-9;
  const viaX = Math.abs(tMin - t1x) <= eps;
  const viaY = Math.abs(tMin - t1y) <= eps;
  let face;
  if (viaX && viaY) face = 'corner';
  else if (viaX) face = prev.x < minX ? 'left' : 'right';
  else face = prev.y < minY ? 'top' : 'bottom';

  return { t, face, x: prev.x + t * dx, y: prev.y + t * dy };
}

